mapper.update:
UPDATE pms_sku_stock
sku_id = #{skuId,jdbcType=BIGINT}, stock = #{stock,jdbcType=INTEGER}, lock_stock = #{lockStock,jdbcType=INTEGER}, sale = #{sale,jdbcType=INTEGER}, low_stock = #{lowStock,jdbcType=INTEGER}, stock_status = #{stockStatus,jdbcType=TINYINT}, version = version + 1,
WHERE id = #{id,jdbcType=BIGINT}

UPDATE pms_sku_stock
SET stock = stock - #{quantity,jdbcType=INTEGER},
    version = version + 1
WHERE sku_id = #{skuId,jdbcType=BIGINT}
  AND version = #{version,jdbcType=INTEGER}
  AND stock >= #{quantity,jdbcType=INTEGER}

UPDATE pms_sku_stock
SET stock = stock - #{quantity,jdbcType=INTEGER},
    lock_stock = lock_stock + #{quantity,jdbcType=INTEGER},
    version = version + 1
WHERE sku_id = #{skuId,jdbcType=BIGINT}
  AND version = #{version,jdbcType=INTEGER}
  AND stock >= #{quantity,jdbcType=INTEGER}

UPDATE pms_sku_stock
SET stock = stock + #{quantity,jdbcType=INTEGER},
    lock_stock = lock_stock - #{quantity,jdbcType=INTEGER},
    version = version + 1
WHERE sku_id = #{skuId,jdbcType=BIGINT}
  AND lock_stock >= #{quantity,jdbcType=INTEGER}

UPDATE pms_sku_stock
SET lock_stock = lock_stock - #{quantity,jdbcType=INTEGER},
    version = version + 1
WHERE sku_id = #{skuId,jdbcType=BIGINT}
  AND lock_stock >= #{quantity,jdbcType=INTEGER}
